<script lang="ts">
  import AppHeader from '$components/AppHeader.svelte'; import { chains } from '$lib/config/chains';
  let owner='';let chainId:number=chains[0].id;let contractsText='';let loading=false;let error='';let fetchedAt='';let tokens:Array<Record<string,unknown>>=[];
  async function discover(){loading=true;error='';tokens=[];try{const contracts=contractsText.split(/[\s,]+/).filter(Boolean);const r=await fetch('/api/tokens',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({owner,chainId,contracts})});const data=await r.json();if(!r.ok)throw new Error(data.error);tokens=data.tokens;fetchedAt=data.fetchedAt;}catch(e){error=e instanceof Error?e.message:'Token discovery failed';}finally{loading=false;}}
  async function connect(){try{const eth=(window as unknown as {ethereum?:{request:(a:{method:string})=>Promise<string[]>}}).ethereum;if(!eth)throw new Error('Install MetaMask first.');owner=(await eth.request({method:'eth_requestAccounts'}))[0]||'';}catch(e){error=e instanceof Error?e.message:'Wallet connection failed';}}
</script>
<svelte:head><title>ERC-20 Token Discovery — Poké</title></svelte:head><AppHeader active="portfolio" />
<main class="route-page discovery-page"><div class="subnav"><a href="/portfolio">← Portfolio</a><span>/</span><strong>ERC-20 token discovery</strong></div><section class="discovery-hero"><div><span class="eyebrow">LIVE CONTRACT LOOKUP</span><h1>ERC-20 token discovery</h1><p>Add known token contracts to retrieve their metadata and the wallet’s live token balance through Poké’s RPC adapter.</p></div><div class="discovery-icon">◎</div></section><section class="discovery-form"><div><label for="token-owner">Wallet address</label><div class="inline-field"><input id="token-owner" bind:value={owner} placeholder="0x wallet address"/><button onclick={connect}>Connect wallet</button></div></div><div><label for="token-chain">Network</label><select id="token-chain" bind:value={chainId}>{#each chains as chain}<option value={chain.id}>{chain.name}</option>{/each}</select></div><div class="full-field"><label for="contracts">ERC-20 contract addresses</label><textarea id="contracts" bind:value={contractsText} placeholder="Paste up to 10 contract addresses, separated by lines or commas"></textarea><small>Public RPC cannot automatically list every token held by a wallet; an indexer adapter can add automatic discovery later.</small></div>{#if error}<p class="discovery-error">{error}</p>{/if}<button class="discover-button" onclick={discover} disabled={loading}>{loading?'Reading token contracts…':'Discover tokens'}</button></section>{#if tokens.length}<section class="discovery-results"><div class="section-head"><div><span class="eyebrow">RESULTS</span><h2>{tokens.length} token contract{tokens.length===1?'':'s'} checked</h2></div><small>{new Date(fetchedAt).toLocaleString()}</small></div><div class="token-grid">{#each tokens as token}<article class:error={token.status==='error'}><div class="token-avatar">{token.symbol?String(token.symbol).slice(0,2):'?'}</div><div class="token-main"><strong>{String(token.name||'Unreadable token')}</strong><span>{String(token.symbol||'Unknown')} · {String(token.contract).slice(0,10)}…</span></div><div class="token-balance"><small>WALLET BALANCE</small><code>{String(token.balance??'—')}</code></div>{#if token.error}<p>{String(token.error)}</p>{/if}</article>{/each}</div></section>{/if}</main>
